class Solution {
  public int sumOfEncryptedInt(int[] nums) {
    int s = 0;
    for (int x : nums) {
      int m = 0, d = 0;
      while (x > 0) {
        m = Math.max(m, x % 10);
        x /= 10;
        d++;
      }
      int v = 0;
      while (d-- > 0) v = v * 10 + m;
      s += v;
    }
    return s;
  }
}
